/**
 * キューバのクイズ。
 *
 * 難易度は1〜10。基準は他の盤面と同じ「その国の外にいる一般的な人が
 * どれくらい答えられそうか」。都市カードで具体的な事実として書いた数字
 * (1837年11月19日・27.5km・1839年末・44.5km・トリニダーのUNESCO登録の
 * 有無・カマグエイ/シエンフエゴスのUNESCO登録年など)は、そのままの形では
 * 問わない。同じ話題でも、都市カードが触れていない角度(技師の出身州、
 * 中央鉄道の資金を出した人物、エレクトリコのその後の町名など)を選んでいる。
 *
 * 南アメリカ・メキシコ・北アメリカ・世界一周の既存クイズは抽出前に
 * 目視で確認し(ハリケーンの語源・野球の人気比較・キューバ―ユカタン海峡・
 *米州機構など)、同じ問いを作っていない。
 *
 * 難易度9〜10は自分で裏取りした。確度が中程度のものはコメントに書いた。
 */
function t(source) {
  const parts = source.split("|");
  if (parts.length !== 4) {
    throw new Error(`4言語(en|es|fr|ja)で書いてください: ${source.slice(0, 60)}…`);
  }
  const [en, es, fr, ja] = parts;
  return { en, es, fr, ja };
}

function q(difficulty, question, options, a, fact) {
  return { difficulty, q: t(question), o: options.map(t), a, f: t(fact) };
}

